      id: `signage-ai-job-${Object.keys(AI_JOBS).length + 1}`,
      state: "queued",
      kind,
      provider: "OPENAI",
      model: "gpt-image-2",
      candidates: count,
      images_produced: 0,
      parent_job_id: request.parent_job_id,
      version: 0,
      prompt: request.prompt,
      images: Array.from({ length: count }, () => null),
      created_at: now()
